fn update(scene: &mut GameScene<'_>, time: &FrameTime) {
    let left = 10 - (time.fixed_tick / 60).min(10) as i32;
    scene.set_counter("time_left", left);
    if left == 0 {
        scene.set_hud("Message", |hud| hud.text = "Time up!".into());
        return;
    }
    if scene.pressed("tap") {
        scene.add_to_counter("score", 1);
    }
}
